<script setup lang="ts">
import{onMounted,computed,ref}from'vue';import{useEngine}from'./stores/engine';import Icon from'./components/Icon.vue';import Modal from'./components/Modal.vue';import{confirmation,answerConfirmation}from'./services/confirm';import{api}from'./services/api';
const e=useEngine();onMounted(e.start);const links=[{path:'/',label:'概览',icon:'home'},{path:'/inputs',label:'AirPlay 接收器',icon:'inputs'},{path:'/speakers',label:'妙播音箱',icon:'speaker'},{path:'/river',label:'River 中心',icon:'river'},{path:'/plus',label:'授权与购买',icon:'shield'},{path:'/settings',label:'设置',icon:'settings'}];const toneActive=computed(()=>['connecting','playing','stopping'].includes(e.tone?.phase||''));const stopping=ref(false);async function stopTone(){stopping.value=true;try{e.setTone(await api('/test-tone/stop','POST'));void e.refresh()}catch(err){e.error=String(err)}finally{stopping.value=false}}
</script>
<template><div class="app-shell"><aside class="sidebar"><RouterLink class="brand" to="/"><span class="brand-symbol"><Icon name="river" :size="29"/></span><span>Air2Mi</span></RouterLink><nav class="main-nav" aria-label="主导航"><RouterLink v-for="link in links" :key="link.path" :to="link.path" :class="{'settings-link':link.path==='/settings'}"><Icon :name="link.icon"/><span>{{link.label}}</span></RouterLink></nav><div class="sidebar-status"><span class="status-dot" :class="{live:e.snapshot?.engine_running}"></span><div><b>{{toneActive?'测试音模式':e.snapshot?.engine_running?'Engine 已连接':e.snapshot?.engine_installed?'Engine 已停止':'等待安装 Engine'}}</b><small>{{e.snapshot?.engine_manifest.kernel_version||'内核独立安装'}}</small></div><RouterLink to="/settings" aria-label="管理内核"><Icon name="chevron" :size="15"/></RouterLink></div></aside><main class="main-content"><div class="mobile-brand"><RouterLink class="mobile-logo" to="/"><span class="brand-symbol"><Icon name="river" :size="20"/></span>Air2Mi</RouterLink><span v-if="e.snapshot" class="mobile-engine-status"><span class="status-dot" :class="{live:e.snapshot.engine_running}"></span>{{ e.snapshot.engine_running ? '内核已连接' : e.snapshot.engine_installed ? '内核已停止' : '待安装内核' }}</span><RouterLink class="mobile-plus-link" to="/plus" aria-label="授权与购买">Air2Mi Plus<Icon name="chevron" :size="13"/></RouterLink></div><div v-if="e.error" role="alert" class="notice error"><Icon name="warning"/><span>{{e.error}}</span><button class="text" @click="e.refresh">重试</button></div><div v-if="toneActive" class="tone-banner" role="status"><Icon name="sound"/><div><b>{{e.tone?.phase==='playing'?'正在播放测试音':e.tone?.phase==='stopping'?'正在恢复 AirPlay 入口':'正在连接测试音箱'}}</b><small>请手动停止；最长 5 分钟自动结束，并恢复原接收器。</small></div><button class="secondary compact" :disabled="stopping" @click="stopTone"><Icon name="stop" :size="16"/>停止</button></div><div v-if="e.loading" class="loading-grid" aria-label="正在连接应用"><div v-for="n in 4" :key="n" class="skeleton"></div></div><RouterView v-else v-slot="{ Component, route }">
        <div :key="route.path" class="route-page"><component :is="Component"/></div>
      </RouterView></main><nav class="mobile-nav" aria-label="移动导航"><RouterLink v-for="link in links.filter(item=>item.path!=='/plus')" :key="link.path" :to="link.path"><Icon :name="link.icon"/><small>{{link.label==='AirPlay 接收器'?'接收器':link.label==='妙播音箱'?'音箱':link.label==='River 中心'?'River':link.label}}</small></RouterLink></nav><Modal :open="!!confirmation" :title="confirmation?.title||''" @close="answerConfirmation(false)"><p class="dialog-copy">{{confirmation?.message}}</p><div class="dialog-actions"><button class="secondary" @click="answerConfirmation(false)">{{confirmation?.cancelLabel}}</button><button @click="answerConfirmation(true)">{{confirmation?.confirmLabel}}</button></div></Modal></div></template>
